#include <stdio.h>

#define ROWS 3
#define COLS 5

int main() {
    char map[ROWS][COLS] = {
        {'#', '#', '#', '#', '#'},
        {'#', '.', 'P', '.', '#'},
        {'#', '#', '#', '#', '#'}
    };
    map[1][3] = 'E';

    for (int r = 0; r < ROWS; r++) {
        for (int c = 0; c < COLS; c++) {
            printf("%c", map[r][c]);
        }
        printf("\n");
    }
    return 0;
}

#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>

int main() {
    FILE *f = fopen("best.txt", "w");
    if (f == NULL) {
        printf("Could not save\n");
        return 1;
    }
    fprintf(f, "%d\n", 120);
    fclose(f);

    int best = 0;
    f = fopen("best.txt", "r");
    if (f != NULL) {
        fscanf(f, "%d", &best);
        fclose(f);
    }
    printf("Best: %d\n", best);
    return 0;
}
